package com.example.riskplatform.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.example.riskplatform.common.BusinessException;import com.example.riskplatform.entity.RiskEvent;import com.example.riskplatform.mapper.RiskEventMapper;import lombok.RequiredArgsConstructor;import com.example.riskplatform.service.rag.CorpusEvents;import org.springframework.stereotype.Service;import java.util.*;
@Service @RequiredArgsConstructor public class RiskEventService{private final RiskEventMapper mapper;private final DataScopeService scope;private final AuditService audit;private final CorpusEvents corpus;public List<RiskEvent>list(Long cid,String status,String level){LambdaQueryWrapper<RiskEvent>w=new LambdaQueryWrapper<>();List<Long>ids=scope.allowedCompanyIds();if(cid!=null){check(cid);w.eq(RiskEvent::getCompanyId,cid);}else if(ids!=null){if(ids.isEmpty())return List.of();w.in(RiskEvent::getCompanyId,ids);}if(status!=null&&!status.isBlank())w.eq(RiskEvent::getStatus,status);if(level!=null&&!level.isBlank())w.eq(RiskEvent::getRiskLevel,level);return mapper.selectList(w.orderByDesc(RiskEvent::getCreatedAt).last("LIMIT 500"));}private void check(Long cid){if(!scope.canAccess(cid))throw new BusinessException(403,"无权访问风险数据");}private RiskEvent get(Long id){RiskEvent e=mapper.selectById(id);if(e==null)throw new BusinessException("风险事件不存在");check(e.getCompanyId());return e;}public RiskEvent assign(Long id,Long uid){RiskEvent e=get(id);e.setAssigneeUserId(uid);e.setStatus("ASSIGNED");mapper.updateById(e);corpus.upsert("event",id,e.getCompanyId());corpus.aggregate(e.getCompanyId());audit.log("ASSIGN","RISK_EVENT",id,"assignee="+uid);return e;}public RiskEvent handle(Long id,String r){RiskEvent e=get(id);e.setHandleResult(r);e.setStatus("HANDLED");mapper.updateById(e);corpus.upsert("event",id,e.getCompanyId());corpus.aggregate(e.getCompanyId());audit.log("HANDLE","RISK_EVENT",id,r);return e;}public RiskEvent review(Long id,String c,boolean ok){RiskEvent e=get(id);e.setReviewComment(c);e.setStatus(ok?"REVIEWED":"ASSIGNED");mapper.updateById(e);corpus.upsert("event",id,e.getCompanyId());corpus.aggregate(e.getCompanyId());audit.log("REVIEW","RISK_EVENT",id,c);return e;}public RiskEvent close(Long id){RiskEvent e=get(id);e.setStatus("CLOSED");mapper.updateById(e);corpus.upsert("event",id,e.getCompanyId());corpus.aggregate(e.getCompanyId());audit.log("CLOSE","RISK_EVENT",id,"closed");return e;}}
